contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // Non-payable fallback: this contract rejects any transfer with msg.value > 0,
    // but accepts plain calls and zero-value transfers.
    fallback() external {}

    function run(uint amount) public payable {
        require(c.owner() == address(this), "caller must be owner");
        require(address(this).balance >= amount, "insufficient funds");

        // Fund c through its payable fallback (top-level statement).
        address(c).call{value: amount}("");

        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }

        // On P, withdrawing a positive balance to a value-rejecting recipient always reverts.
        // On M, only 0 is transferred (value 0 is accepted), so it completes for any amount.
        assert(amount == 0 || reverted);
    }
}

